const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Smith Island location (Chesapeake Bay)
  const smithIsland = ee.Geometry.Point([-76.14, 37.25]).buffer(2000);

  // 1999: Landsat 7 ETM+ data
  const col1999 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(smithIsland)
    .filterDate('1999-06-01', '1999-09-30')
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  const size1999 = col1999.size().getInfo();
  console.log(`1999 Images: ${size1999}`);

  if (size1999 === 0) {
    console.log('No data for 1999.');
    console.log('C1');
    return;
  }

  // 2019: Landsat 8 OLI data
  const col2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(smithIsland)
    .filterDate('2019-06-01', '2019-09-30')
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  const size2019 = col2019.size().getInfo();
  console.log(`2019 Images: ${size2019}`);

  if (size2019 === 0) {
    console.log('No data for 2019.');
    console.log('C1');
    return;
  }

  // Process 1999 image
  const img1999 = col1999.median();
  const ndvi1999 = img1999.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
  const land1999 = ndvi1999.gt(0.3); // Threshold for land

  const count1999 = land1999.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: smithIsland,
    scale: 30,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`1999 Land pixels: ${count1999}`);

  if (count1999 === 0) {
    console.log('No valid land pixels in 1999.');
    console.log('C2');
    return;
  }

  // Process 2019 image
  const img2019 = col2019.median();
  const ndvi2019 = img2019.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
  const land2019 = ndvi2019.gt(0.3);

  const count2019 = land2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: smithIsland,
    scale: 30,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`2019 Land pixels: ${count2019}`);

  if (count2019 === 0) {
    console.log('No valid land pixels in 2019.');
    console.log('C2');
    return;
  }

  // Calculate land areas
  const area1999 = count1999 * 30 * 30 / 1e6; // convert to km²
  const area2019 = count2019 * 30 * 30 / 1e6;

  console.log(`1999 Land area: ${area1999.toFixed(2)} km²`);
  console.log(`2019 Land area: ${area2019.toFixed(2)} km²`);
  console.log(`Area change: ${(area2019 - area1999).toFixed(2)} km²`);

  // Validate results
  if (area1999 === null || area2019 === null || isNaN(area1999) || isNaN(area2019)) {
    console.log('C3');
    return;
  }

  // Answer: Did land area decrease?
  if (area1999 > area2019) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
